// Python <-> JS parity (Vitest). Copy to CovertCook/src/lib/foodModel.test.ts and the fixture to
// CovertCook/src/lib/__fixtures__/parity.json (generated by: python -m scripts.export_web_fixtures --run <run>).
import { describe, expect, it, vi } from "vitest";

vi.mock("onnxruntime-web", () => ({ env: { wasm: {} }, InferenceSession: {}, Tensor: class {} }));

import { postprocess, toTensorData, type ModelMeta } from "./foodModel";
import fixture from "./__fixtures__/parity.json";

const meta = {
  resolution: fixture.resolution, mean: fixture.mean, std: fixture.std, thresholds: fixture.thresholds,
  ingredient_names: fixture.ingredient_names, ingredient_ids: fixture.ingredient_names.map((_: string, k: number) => k + 1),
  outputs: { ingredients: "ingredients" }, dish_names: [], unknown_dish_min_prob: null,
} as unknown as ModelMeta;

describe("preprocessing matches Python", () => {
  for (const item of fixture.items) {
    it(`toTensorData ${item.key}`, () => {
      const t = toTensorData(item.rgb, fixture.resolution, fixture.mean, fixture.std, 3);
      let maxDiff = 0;
      for (let i = 0; i < t.length; i++) maxDiff = Math.max(maxDiff, Math.abs(t[i] - item.tensor[i]));
      expect(maxDiff).toBeLessThan(1e-4);
    });
  }
});

describe("postprocessing matches Python", () => {
  for (const item of fixture.items) {
    it(`postprocess ${item.key}`, () => {
      const r = postprocess(item.probs, null, meta);
      expect(r.ingredients.map((i) => i.name).sort()).toEqual([...item.ingredients].sort());
    });
  }
});
